events.onValueChange:
function(form) {
  var multi_select = form.get('2MT5Y_Diagnosis').currentRecord.value.value;
  var length = multi_select == undefined ? 0 : multi_select.length;
  var arr = []
  if (length == 0) {
    form.get("CCS_other_diagnosis").setHidden(true);
  } else {
    for (var i = 0; i < length; i++) {
      var name = multi_select[i].displayString == undefined ? multi_select[i].name : multi_select[i].displayString;
      arr.push(name);
      if (arr.includes('Other_Diagnosis'))
        form.get("CCS_other_diagnosis").setHidden(false);
      else
        form.get("CCS_other_diagnosis").setHidden(true);
    }
  }
}

function(form) {
  if (form.get('Subscription card').getValue() === 'Yes') {
    form.get('Subscription card Numbers').setHidden(false);
  } else {
    form.get('Subscription card Numbers').setHidden(true);
  }
}
